// Extract youtube_video_id and generate a job_id
const input = $input.first().json.body || $input.first().json;
const youtube_video_id = input.youtube_video_id;
const audio_url = input.audio_url;
const language = input.language || 'fr';

if (!youtube_video_id && !audio_url) {
  throw new Error('youtube_video_id or audio_url is required');
}

// Simple job_id: timestamp + random hex
const job_id = `job_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`;

// Build Runpod input payload
const runpodInput = { job_id, language };
if (youtube_video_id) {
  runpodInput.youtube_video_id = youtube_video_id;
} else {
  runpodInput.audio_url = audio_url;
}

return [{
  json: {
    job_id,
    youtube_video_id: youtube_video_id || null,
    audio_url: audio_url || null,
    runpod_payload: { input: runpodInput },
  }
}];

// Combine Runpod response with job info
const runpodResponse = $input.first().json;
const jobInfo = $('Prepare Runpod Payload').first().json;

return [{
  json: {
    job_id: jobInfo.job_id,
    runpod_job_id: runpodResponse.id,
    status: runpodResponse.status,
    youtube_video_id: jobInfo.youtube_video_id,
  }
}];
